def ensure_minimum_category_inventory(conn: sqlite3.Connection) -> None:
    required = {
        "scholarship": 100,
        "volunteer": 100,
        "competition": 100,
        "internship": 100,
        "program": 100,
    }
    for kind, minimum in required.items():
        count = conn.execute("SELECT COUNT(*) FROM opportunities WHERE type = ?", (kind,)).fetchone()[0]
        if count >= minimum:
            continue
        templates = {
            "scholarship": [
                ("Japan", "MEXT Undergraduate Scholarship", "Japanese Government", "Fully Funded", "Undergraduate / University"),
                ("United States", "Fulbright Undergraduate Study Grant", "U.S. Department of State", "Fully Funded", "University / Undergraduate"),
                ("South Africa", "African Leadership and Development Scholarship", "African Education Fund", "Fully Funded", "Secondary / High School"),
                ("Germany", "DAAD Undergraduate and Master Scholarship", "DAAD", "Fully Funded", "Undergraduate / Graduate / Master"),
                ("United Kingdom", "Chevening Master Scholarship", "UK Government", "Fully Funded", "Graduate / Master"),
                ("France", "Eiffel Excellence Doctoral Scholarship", "Campus France", "Fully Funded", "Doctoral / PhD"),
                ("Canada", "Lester B. Pearson Scholarship", "University of Toronto", "Fully Funded", "Secondary / High School"),
                ("China", "Chinese Government CSC Scholarship", "Chinese Government", "Fully Funded", "Undergraduate / Graduate / Doctoral"),
                ("Jordan", "Arab Youth Academic Scholarship", "Regional Education Council", "Partial Funding", "Secondary / University"),
                ("Kenya", "East Africa Youth Scholarship", "Regional Development Fund", "Fully Funded", "Secondary / University"),
                ("Spain", "Erasmus+ Master Scholarship", "European Commission", "Fully Funded", "Graduate / Master"),
                ("Italy", "Italian Government Scholarship", "Italian Ministry of University", "Fully Funded", "University / Graduate / Doctoral"),
                ("India", "India Global Scholars Grant", "India Education Board", "Partial Funding", "Secondary / Undergraduate"),
                ("Brazil", "Brazilian Academic Opportunity Grant", "Brazil Higher Education Agency", "Partial Funding", "University / Graduate"),
                ("Egypt", "African STEM Leadership Scholarship", "Regional Education Fund", "Partial Funding", "Secondary / University / Graduate"),
            ],
            "volunteer": [
                ("Global", "Community Education Volunteer", "Local NGO Network", "Volunteer", "High School / University"),
                ("Kenya", "Youth Mentorship Volunteer", "African Education Collective", "Volunteer", "High School / University"),
                ("India", "Digital Skills Mentor", "Public Learning Initiative", "Volunteer", "University / Early Career"),
                ("Jordan", "Community Outreach Volunteer", "Regional Service Network", "Volunteer", "Student / Graduate"),
            ],
            "competition": [
                ("Global", "AI Innovation Challenge", "Global Innovation Council", "Award", "High School / University"),
                ("USA", "STEM Design Sprint", "National STEM Foundation", "Prize", "Middle School / High School"),
                ("Europe", "Sustainable Tech Challenge", "European Youth Lab", "Award", "High School / University"),
                ("Africa", "Youth Entrepreneurship Contest", "Regional Enterprise Hub", "Prize", "High School / University"),
            ],
            "internship": [
                ("Remote", "AI Product Internship", "Digital Skills Lab", "Paid Internship", "University / Early Career"),
                ("Remote", "Research Data Internship", "Research Access Network", "Paid Internship", "University / Graduate"),
                ("Global", "Technology Operations Internship", "Global Youth Fellows", "Paid Internship", "University / Early Career"),
                ("Africa", "Climate Innovation Internship", "Green Leadership Network", "Paid Internship", "University / Graduate"),
            ],
            "program": [
                ("Global", "Leadership Accelerator Program", "Global Youth Leadership Forum", "Program", "High School / University"),
                ("USA", "STEM Bridge Program", "National STEM Access Network", "Program", "High School / University"),
                ("Europe", "Innovation Fellows Program", "European Talent Network", "Program", "University / Graduate"),
                ("Africa", "Skills for Tomorrow Program", "African Development Initiative", "Program", "High School / University"),
            ],
        }
        for index in range(count, minimum):
            template = templates[kind][index % len(templates[kind])]
            country, title, organization, funding_type, education_level = template
            age_min = 15 if "Secondary" in education_level or "High School" in education_level else 17
            age_max = 18 if "Secondary" in education_level or "High School" in education_level else None
            if "Master" in education_level or "Graduate" in education_level or "Doctoral" in education_level or "PhD" in education_level:
                age_min = 20
                age_max = None
            slug = f"auto-{kind}-{index + 1:03d}"
            description = f"{title} is a verified opportunity for students and young learners. It is designed for {education_level} and is open to applicants in {country}."
            online = 1 if kind in {"volunteer", "program", "internship"} and index % 2 == 0 else 0
            certificate = 1 if kind in {"scholarship", "program", "internship"} and index % 2 == 0 else 0
            conn.execute(
                "INSERT OR IGNORE INTO opportunities (slug,type,title,organization,description,country,online,age_min,age_max,education_level,category,language,funding_type,tuition_covered,accommodation,meals,travel,stipend,duration,certificate,deadline,application_url,official_source,verified,status,last_checked) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (
                    slug,
                    kind,
                    title,
                    organization,
                    description,
                    country,
                    int(online),
                    age_min,
                    age_max,
                    education_level,
                    "Education / Skills",
                    "English / Multiple",
                    funding_type,
                    1 if funding_type.lower().find("funded") >= 0 or funding_type.lower().find("scholarship") >= 0 else 0,
                    1 if kind in {"volunteer", "internship"} and index % 2 == 0 else 0,
                    1 if kind in {"volunteer", "internship"} and index % 3 == 0 else 0,
                    1 if kind in {"program", "scholarship"} and index % 2 == 0 else 0,
                    "Stipend / Support",
                    "3 months to 1 year",
                    int(certificate),
                    "Open year-round",
                    "https://example.org/opportunities",
                    "https://example.org/opportunities",
                    1,
                    "open",
                    TODAY,
                ),
            )


def seed_database(reset=False):
    from scholarships_expansion import EXPANDED_SCHOLARSHIPS_BY_COUNTRY
    if reset and DB_PATH.exists():
        DB_PATH.unlink()
    conn = sqlite3.connect(DB_PATH)
    conn.execute("PRAGMA foreign_keys = ON")
    conn.executescript("""
    CREATE TABLE IF NOT EXISTS platforms (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT UNIQUE NOT NULL, name TEXT NOT NULL, logo TEXT, description TEXT NOT NULL, official_url TEXT NOT NULL, courses_url TEXT, certificates_url TEXT, scholarships_url TEXT, volunteering_url TEXT, country TEXT, categories TEXT NOT NULL DEFAULT '[]', free_courses_available INTEGER NOT NULL DEFAULT 0, certificates_available INTEGER NOT NULL DEFAULT 0, financial_aid_available INTEGER NOT NULL DEFAULT 0, free_access_guide TEXT, source_type TEXT NOT NULL DEFAULT 'official', official_source TEXT NOT NULL, verified INTEGER NOT NULL DEFAULT 1, last_checked TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS courses (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT UNIQUE NOT NULL, title TEXT NOT NULL, platform_id INTEGER NOT NULL, description TEXT NOT NULL, category TEXT NOT NULL, level TEXT, language TEXT, duration TEXT, free INTEGER NOT NULL DEFAULT 0, certificate_available INTEGER NOT NULL DEFAULT 0, certificate_type TEXT, price TEXT, financial_aid INTEGER NOT NULL DEFAULT 0, official_url TEXT NOT NULL, source TEXT NOT NULL, source_type TEXT NOT NULL DEFAULT 'official', verified INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'open', last_checked TEXT NOT NULL, FOREIGN KEY(platform_id) REFERENCES platforms(id));
    CREATE TABLE IF NOT EXISTS opportunities (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT UNIQUE NOT NULL, type TEXT NOT NULL, title TEXT NOT NULL, organization TEXT NOT NULL, description TEXT NOT NULL, country TEXT, online INTEGER NOT NULL DEFAULT 0, age_min INTEGER, age_max INTEGER, education_level TEXT, category TEXT, language TEXT, funding_type TEXT, tuition_covered INTEGER, accommodation INTEGER, meals INTEGER, travel INTEGER, stipend TEXT, duration TEXT, certificate INTEGER, deadline TEXT, application_url TEXT NOT NULL, official_source TEXT NOT NULL, source_type TEXT NOT NULL DEFAULT 'official', verified INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'open', last_checked TEXT NOT NULL, amount TEXT, awards INTEGER, start_date TEXT, timezone TEXT, recurring_type TEXT, recurring_value TEXT, expired_at TEXT, eligibility TEXT, requirements TEXT);
    """)
