    for c in MORE_COURSES:
        slug,title,platform,desc,cat,level,lang,duration,free,cert_avail,cert_type,price,aid,url = c
        pid_row = conn.execute("SELECT id FROM platforms WHERE slug=?", (platform,)).fetchone()
