        conn.execute("INSERT OR IGNORE INTO opportunities (slug,type,title,organization,description,country,online,age_min,age_max,education_level,category,language,funding_type,tuition_covered,accommodation,meals,travel,stipend,duration,certificate,deadline,application_url,official_source,verified,status,last_checked) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)", (slug,typ,title,org,desc,country,int(online),amin,amax,edu,cat,lang,funding,tuition,accom,meals,travel,stipend,duration,certificate,deadline,url,source,1,"open",TODAY))
