def merge_expanded_catalog():
    from expansion_data import EXPANDED_OPPORTUNITIES, EXPANDED_PLATFORMS
    from additional_catalog import ADDITIONAL_OPPORTUNITIES
    conn = sqlite3.connect(DB_PATH)
    conn.execute("PRAGMA foreign_keys = ON")
    for item in EXPANDED_PLATFORMS:
        slug = item["slug"]
        exists = conn.execute("SELECT 1 FROM platforms WHERE slug=?", (slug,)).fetchone()
        if exists:
            continue
        conn.execute(
            """INSERT OR IGNORE INTO platforms
            (slug,name,description,official_url,courses_url,scholarships_url,volunteering_url,country,categories,
             free_courses_available,certificates_available,financial_aid_available,free_access_guide,official_source,verified,last_checked)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                slug,
                item["name"],
                f"منصة أو جهة رسمية للتعلم أو التطوع والفرص التعليمية من {item['name']}.",
                item["official_url"],
                item["official_url"],
                item["official_url"],
                item["official_url"],
                "Global",
                json.dumps(["Volunteering", "Education", "Opportunities"], ensure_ascii=False),
                0, 0, 0,
                "راجع الفرص المجانية وشروط كل فرصة في المصدر الرسمي.",
                item["official_url"], 1, TODAY,
            ),
        )
    existing = {r[0] for r in conn.execute("SELECT slug FROM opportunities").fetchall()}
    for item in EXPANDED_OPPORTUNITIES:
        if item["id"] in existing:
            continue
        conn.execute(
            """INSERT OR IGNORE INTO opportunities
            (slug,type,title,organization,description,country,online,education_level,category,language,funding_type,
             certificate,deadline,application_url,official_source,verified,status,last_checked,eligibility,requirements)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                item["id"],
                item["type"],
                item["title"],
                item.get("organization") or item.get("provider", ""),
                item.get("description") or item.get("about_opportunity", ""),
                item.get("country"),
                int(bool(item.get("online"))),
                item.get("education_level") or item.get("target_group"),
                item.get("category"),
                "العربية / الإنجليزية",
                item.get("funding_type"),
                int(bool(item.get("certificate"))),
                item.get("deadline"),
                item.get("official_link"),
                item.get("official_link"),
                1,
                "open",
                TODAY,
                json.dumps(item.get("eligibility_criteria", []), ensure_ascii=False),
                json.dumps(item.get("required_documents", []), ensure_ascii=False),
            ),
        )
    for item in ADDITIONAL_OPPORTUNITIES:
        (slug, typ, title, organization, description, country, online, education_level, category, language, funding_type, official_link) = item
        conn.execute(
            """INSERT OR IGNORE INTO opportunities
            (slug,type,title,organization,description,country,online,education_level,category,language,funding_type,
             certificate,application_url,official_source,verified,status,last_checked)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (slug, typ, title, organization, description, country, int(online), education_level, category, language,
             funding_type, 0, official_link, official_link, 1, "open", TODAY),
        )
    conn.commit()
    conn.close()


if __name__ == "__main__":
    seed_database(reset="--reset" in sys.argv)
    merge_expanded_catalog()
    conn = sqlite3.connect(DB_PATH)
    merge_language_catalog(conn=conn)
    merge_extra_language_platforms(conn)
    conn.close()
    from verified_brand_courses import run as run_verified_brand_courses
    run_verified_brand_courses()
    import brand_additions_2
    print(f"Seeded database: {DB_PATH}")
